local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local reverse = {}
for i = 1, #alphabet do
    reverse[string.sub(alphabet, i, i)] = i - 1
end

local function decodeBase64(data)
    data = string.gsub(data, "[^" .. alphabet .. "=]", "")
    local output = {}
    local buffer, bits = 0, 0

    for i = 1, #data do
        local c = string.sub(data, i, i)
        if c ~= "=" then
            local value = reverse[c]
            if value ~= nil then
                buffer = buffer * 64 + value
                bits = bits + 6

                if bits >= 8 then
                    bits = bits - 8
                    local byte = math.floor(buffer / (2 ^ bits)) % 256
                    output[#output + 1] = string.char(byte)
                    buffer = buffer % (2 ^ bits)
                end
            end
        end
    end

    return table.concat(output)
end

local source = decodeBase64(encoded)
local compiled, compileError = loadstring(source)

if not compiled then
    error("YVONE HUB compile error: " .. tostring(compileError))
end

return compiled()

